/* 临时校验脚本（不属于交付物）：token 对比度、变量引用完整性、禁用字符、结构检查 */
const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');

/* ---------- 1. 抓取两套主题的 token ---------- */
function tokens(blockStart) {
  const i = html.indexOf(blockStart);
  const seg = html.slice(i, html.indexOf('}', i));
  const out = {};
  for (const m of seg.matchAll(/--([\w-]+):\s*([^;]+);/g)) out[m[1]] = m[2].trim();
  return out;
}
const light = tokens(':root {\n  color-scheme: light;');
const dark = tokens(':root[data-theme="dark"]');

/* ---------- 2. 对比度 ---------- */
const hex = h => {
  h = h.replace('#', '');
  if (h.length === 3) h = h.split('').map(c => c + c).join('');
  return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) / 255);
};
const lum = rgb => rgb.map(c => (c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4)))
  .reduce((a, c, i) => a + [0.2126, 0.7152, 0.0722][i] * c, 0);
const ratio = (a, b) => {
  const [x, y] = [lum(hex(a)), lum(hex(b))].sort((m, n) => n - m);
  return (x + 0.05) / (y + 0.05);
};

const pairs = [
  ['正文 text / bg', 'text', 'bg'],
  ['正文 text / surface', 'text', 'surface'],
  ['次要文字 muted / surface', 'text-muted', 'surface'],
  ['次要文字 muted / bg', 'text-muted', 'bg'],
  ['次要文字 muted / surface-2', 'text-muted', 'surface-2'],
  ['主按钮文字 accent-text / accent', 'accent-text', 'accent'],
  ['主按钮 hover 文字 / accent-hover', 'accent-text', 'accent-hover'],
  ['链接 accent / surface', 'accent', 'surface'],
  ['链接 accent / bg', 'accent', 'bg'],
  ['徽标文字 accent-soft-text / accent-soft', 'accent-soft-text', 'accent-soft'],
  ['错误文字 danger / surface', 'danger', 'surface'],
  ['错误文字 danger / danger-soft', 'danger', 'danger-soft'],
  ['成功文字 success / success-soft', 'success', 'success-soft'],
  ['焦点环 focus / bg（≥3:1）', 'focus', 'bg', 3],
  ['焦点环 focus / surface（≥3:1）', 'focus', 'surface', 3],
  ['边框 border-strong / surface（≥3:1）', 'border-strong', 'surface', 3],
];

let worst = 99;
for (const [label, tk, theme] of [['light'], ['dark']]) { /* noop, keep shape */ }
for (const [name, t] of [['浅色', light], ['深色', dark]]) {
  console.log('\n== ' + name + '主题 ==');
  for (const [label, a, b, min = 4.5] of pairs) {
    const r = ratio(t[a], t[b]);
    const ok = r >= min;
    worst = Math.min(worst, r / min);
    console.log(`${ok ? 'PASS' : 'FAIL'}  ${r.toFixed(2)}:1 (需 ${min})  ${label}  [${t[a]} on ${t[b]}]`);
  }
}

/* ---------- 3. 变量引用完整性 ---------- */
const defined = new Set([...Object.keys(light), ...Object.keys(dark)]);
const used = new Set([...html.matchAll(/var\(--([\w-]+)\)/g)].map(m => m[1]));
const missing = [...used].filter(v => !defined.has(v));
console.log('\n未定义的 token 引用:', missing.length ? missing : '无');
const unused = [...defined].filter(v => !used.has(v));
console.log('已定义但未使用:', unused.length ? unused : '无');

/* ---------- 4. 禁用字符：emoji / 表情 ---------- */
const emoji = [...html.matchAll(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{FE0F}\u{2190}-\u{21FF}\u{2700}-\u{27BF}]/gu)].map(m => m[0]);
console.log('\nemoji / 符号类字符:', emoji.length ? [...new Set(emoji)] : '无');

/* ---------- 5. 结构检查 ---------- */
const checks = {
  '唯一 h1': (html.match(/<h1/g) || []).length === 1,
  '所有 <a> 有 href': !/<a(?![^>]*href)/.test(html),
  '所有 <button> 有 type': !/<button(?![^>]*type=)/.test(html),
  '所有 input/select 有 id+name': (html.match(/<(input|select)\b[^>]*>/g) || [])
    .every(t => /id="/.test(t) && /name="/.test(t)),
  '所有 input/select 有 label': ['email', 'city', 'consent']
    .every(id => html.includes(`for="${id}"`) && html.includes(`id="${id}"`)),
  '表单 novalidate + 阻止默认提交': html.includes('novalidate') && html.includes('preventDefault'),
  '图片/SVG 均为内联（无 http 资源）': !/(src|href)="https?:\/\//.test(html),
  '无非 data: 的外部样式/脚本': !/<link[^>]+stylesheet/.test(html) && !/<script[^>]+src=/.test(html),
  'reduced-motion 媒体查询': html.includes('prefers-reduced-motion: reduce'),
  'focus-visible 焦点环': html.includes(':focus-visible'),
  '跳转链接存在': html.includes('class="skip-link"'),
  '无内联 style 补丁': !/style="/.test(html),
  '正文 16px/1.5': /font-size: 16px;/.test(html) && /line-height: 1\.5;/.test(html),
};
console.log('\n== 结构检查 ==');
for (const [k, v] of Object.entries(checks)) console.log(`${v ? 'PASS' : 'FAIL'}  ${k}`);

/* ---------- 6. 固定宽度扫描（375px 溢出风险） ---------- */
const widths = [...html.matchAll(/\b(width|min-width|flex-basis)\s*:\s*(\d+)px/g)].map(m => +m[2]);
console.log('\n出现 >=360px 的固定宽度:', widths.filter(w => w >= 360).length ? widths.filter(w => w >= 360) : '无');
console.log('最小的整体余量比:', worst.toFixed(2), '（>=1 表示全部达标）');

