/* 临时浏览器验收 harness（不属于交付物）
   用法: node browser-test.js
   对 index.html 的副本注入诊断脚本，用 headless Chrome 在 375/1440 × light/dark 下实测。 */
const fs = require('fs');
const { execFileSync } = require('child_process');

const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const SRC = 'index.html';
const TEST = '.selftest.html';

let html = fs.readFileSync(SRC, 'utf8');

/* 1) 最早的错误收集器 */
html = html.replace('<head>', `<head>
<script>
window.__errs = [];
window.addEventListener('error', function (e) {
  window.__errs.push('error: ' + (e.message || e.type) + (e.filename ? ' @' + e.filename + ':' + e.lineno : ''));
}, true);
window.addEventListener('unhandledrejection', function (e) { window.__errs.push('rejection: ' + e.reason); });
['error', 'warn'].forEach(function (k) {
  var orig = console[k];
  console[k] = function () { window.__errs.push('console.' + k + ': ' + Array.prototype.join.call(arguments, ' ')); return orig.apply(console, arguments); };
});
</script>`);

/* 2) 诊断脚本：布局 / 触控目标 / Tab 顺序 / 表单流程 / 主题可读性 */
html = html.replace('</body>', `<script>
(function () {
  function rect(el) { var r = el.getBoundingClientRect(); return { w: +r.width.toFixed(1), h: +r.height.toFixed(1), r: +r.right.toFixed(1), l: +r.left.toFixed(1) }; }
  function id(el) {
    return el.tagName.toLowerCase()
      + (el.id ? '#' + el.id : '')
      + (el.className && typeof el.className === 'string' ? '.' + el.className.trim().split(/\\s+/).join('.') : '')
      + (el.textContent ? ' "' + el.textContent.trim().slice(0, 14) + '"' : '');
  }

  var d = {};

  /* --- 主题 --- */
  var cs = getComputedStyle(document.documentElement);
  d.theme = document.documentElement.getAttribute('data-theme');
  d.themeApplied = {
    bg: cs.getPropertyValue('--color-bg').trim(),
    text: cs.getPropertyValue('--color-text').trim(),
    accent: cs.getPropertyValue('--color-accent').trim()
  };
  d.bodyText = getComputedStyle(document.body).color + ' on ' + getComputedStyle(document.body).backgroundColor;
  d.font = getComputedStyle(document.body).fontSize + ' / ' + getComputedStyle(document.body).lineHeight;

  /* --- 横向溢出 --- */
  d.viewport = window.innerWidth;
  d.scrollWidth = document.documentElement.scrollWidth;
  d.bodyScrollWidth = document.body.scrollWidth;
  d.overflowing = [];
  Array.prototype.forEach.call(document.querySelectorAll('body *'), function (el) {
    var r = el.getBoundingClientRect();
    if (r.width === 0 && r.height === 0) return;
    if (r.right > window.innerWidth + 0.5 || r.left < -0.5) d.overflowing.push(id(el) + ' → ' + JSON.stringify(rect(el)));
  });

  /* --- 触控目标 --- */
  d.smallTargets = [];
  Array.prototype.forEach.call(document.querySelectorAll('a[href], button, input, select'), function (el) {
    if (el.closest('.skip-link')) return;
    var r = rect(el);
    if (r.w < 44 || r.h < 44) d.smallTargets.push(id(el) + ' → ' + r.w + 'x' + r.h);
  });

  /* --- Tab 顺序 --- */
  d.focusables = Array.prototype.filter.call(
    document.querySelectorAll('a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])'),
    function (el) { return el.offsetParent !== null || el === document.activeElement || el.getClientRects().length; }
  ).map(id);

  /* --- 表单流程自测 --- */
  var form = document.getElementById('signup-form');
  var status = document.getElementById('form-status');
  var email = document.getElementById('email');
  var city = document.getElementById('city');
  var consent = document.getElementById('consent');
  function visible(el) { return el && !el.hidden && el.getClientRects().length > 0; }
  function errText(n) { var e = document.getElementById(n + '-error'); return visible(e) ? e.textContent.trim() : ''; }
  d.form = {};

  form.requestSubmit();                      /* 1. 空表单提交 */
  d.form.empty = {
    emailErr: errText('email'), cityErr: errText('city'), consentErr: errText('consent'),
    emailInvalid: email.getAttribute('aria-invalid'),
    focus: document.activeElement.id,
    status: status.textContent.trim(),
    statusRole: status.getAttribute('role')
  };

  email.value = 'nightrider@';               /* 2. 邮箱格式错误 */
  form.requestSubmit();
  d.form.badEmail = { emailErr: errText('email'), focus: document.activeElement.id };

  email.value = 'nightrider@example.com';    /* 3. 合法提交 */
  city.value = 'shanghai';
  consent.checked = true;
  form.requestSubmit();
  d.form.valid = {
    status: status.textContent.trim(),
    statusVisible: visible(status),
    emailErrAfter: errText('email'),
    emailInvalidAfter: email.getAttribute('aria-invalid'),
    valueReset: email.value === '' && city.value === '' && consent.checked === false
  };

  /* 4. 失焦校验：输入非法值后 blur，应即时提示 */
  email.value = 'oops';
  email.dispatchEvent(new Event('blur'));
  d.form.onBlur = { emailErr: errText('email') };
  email.value = '';
  email.dispatchEvent(new Event('input'));

  /* --- 主题切换行为 --- */
  var toggle = document.getElementById('theme-toggle');
  var before = document.documentElement.getAttribute('data-theme');
  toggle.click();
  var after = document.documentElement.getAttribute('data-theme');
  d.toggle = { before: before, after: after, label: toggle.getAttribute('aria-label'), changed: before !== after };
  toggle.click();
  d.toggle.restored = document.documentElement.getAttribute('data-theme') === before;

  d.errs = window.__errs || [];

  var pre = document.createElement('pre');
  pre.id = '__diag';
  pre.textContent = JSON.stringify(d);
  document.documentElement.appendChild(pre);
})();
</script></body>`);

fs.writeFileSync(TEST, html);

/* 运行四种组合 */
const url = 'file:///' + process.cwd().replace(/\\/g, '/') + '/' + TEST;
const runs = [];
for (const width of [375, 1440]) {
  for (const theme of ['light', 'dark']) {
    const out = execFileSync(CHROME, [
      '--headless=new', '--disable-gpu', '--no-sandbox', '--hide-scrollbars',
      '--virtual-time-budget=4000', '--window-size=' + width + ',900',
      '--dump-dom', url + '?theme=' + theme
    ], { encoding: 'utf8', maxBuffer: 1024 * 1024 * 64, stdio: ['ignore', 'pipe', 'ignore'] });
    const m = out.match(/<pre id="__diag">([\s\S]*?)<\/pre>/);
    if (!m) { console.log('!! ' + width + '/' + theme + ' 未取到诊断数据'); continue; }
    runs.push({ width, theme, d: JSON.parse(m[1]) });
  }
}

/* 报告 */
for (const { width, theme, d } of runs) {
  console.log('\n================ ' + width + 'px / ' + theme + ' ================');
  console.log('theme 属性        :', d.theme, JSON.stringify(d.themeApplied));
  console.log('body 计算样式     :', d.bodyText, '|', d.font);
  console.log('viewport/scrollW  :', d.viewport, '/', d.scrollWidth, '| body', d.bodyScrollWidth,
    (d.scrollWidth <= d.viewport && d.bodyScrollWidth <= d.viewport) ? 'OK 无横向滚动' : '!! 横向溢出');
  console.log('溢出元素          :', d.overflowing.length ? d.overflowing : '无');
  console.log('小于 44x44 的目标 :', d.smallTargets.length ? d.smallTargets : '无');
  console.log('Tab 可达元素 (' + d.focusables.length + '):');
  d.focusables.forEach((f, i) => console.log('   ' + String(i + 1).padStart(2) + '. ' + f));
  console.log('控制台错误        :', d.errs.length ? d.errs : '无');
  if (width === 375 && theme === 'light') {
    console.log('--- 表单自测 ---');
    console.log('空表单提交 :', JSON.stringify(d.form.empty, null, 1));
    console.log('邮箱格式错 :', JSON.stringify(d.form.badEmail));
    console.log('合法提交   :', JSON.stringify(d.form.valid, null, 1));
    console.log('失焦校验   :', JSON.stringify(d.form.onBlur));
    console.log('主题切换   :', JSON.stringify(d.toggle));
  }
}

