arguments.content:
/* 临时 CDP 验收（不属于交付物）：node cdp-test.mjs
   真实时间 + Emulation 真机视口，验证：
   1) 入场动效结束后内容 opacity 是否为 1（不能停在 0）
   2) 375 / 1440 视口下无横向滚动
   3) prefers-reduced-motion: reduce 时动效是否真的被关掉且文字仍可见
   4) 全程控制台无报错 */
import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';

const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const PORT = 9333;
const PAGE = 'file:///' + process.cwd().replace(/\\/g, '/') + '/.selftest.html';

class CDP {
  constructor(ws) {
    this.ws = ws; this.id = 0; this.pending = new Map();
    ws.onmessage = (e) => {
      const m = JSON.parse(e.data);
      if (m.id && this.pending.has(m.id)) {
        const { resolve, reject } = this.pending.get(m.id);
        this.pending.delete(m.id);
        m.error ? reject(new Error(JSON.stringify(m.error))) : resolve(m.result);
      }
    };
  }
  send(method, params) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params: params || {} }));
    });
  }
  async eval(expr) {
    const r = await this.send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
    if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || 'eval failed');
    return r.result.value;
  }
}

const chrome = spawn(CHROME, [
  '--headless=new', '--disable-gpu', '--no-sandbox', '--hide-scrollbars',
  '--allow-file-access-from-files', '--remote-debugging-port=' + PORT,
  '--user-data-dir=' + process.cwd() + '/.chrome-profile',
  '--window-size=1500,900', 'about:blank'
], { stdio: 'ignore' });

/* 等 DevTools 端点就绪 */
let target = null;
for (let i = 0; i < 60 && !target; i++) {
  await sleep(250);
  try {
    const list = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();
    target = list.find(t => t.type === 'page');
  } catch (e) { /* 还没起来 */ }
}
if (!target) { console.log('无法连接 Chrome DevTools'); chrome.kill(); process.exit(1); }

const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
const cdp = new CDP(ws);
await cdp.send('Page.enable');
await cdp.send('Runtime.enable');

/* 读取「动效全部结束后」的状态；getAnimations().finished 只在动画真正完成时 resolve */
const PROBE = `(async () => {
  const wait = ms => new Promise(r => setTimeout(r, ms));
  const sels = ['.badge', 'h1', '.hero-lede', '.hero-actions', '.hero-stats', '.route-card'];
  const els = sels.map(s => document.querySelector(s)).filter(Boolean);
  const anims = els.flatMap(e => e.getAnimations());
  await Promise.all(anims.map(a => a.finished.catch(() => {})));
  await wait(200);
  const opacity = {};
  sels.forEach(s => { const e = document.querySelector(s); if (e) opacity[s] = getComputedStyle(e).opacity; });
  const h1cs = getComputedStyle(document.querySelector('h1'));
  const overflowing = [];
  document.querySelectorAll('body *').forEach(el => {
    const r = el.getBoundingClientRect();
    if (r.width === 0 && r.height === 0) return;
    if (r.right > window.innerWidth + 0.5 || r.left < -0.5) overflowing.push(el.tagName + '.' + el.className + ' ' + JSON.stringify({l:+r.left.toFixed(1), r:+r.right.toFixed(1)}));
  });
  return JSON.stringify({
    viewport: window.innerWidth,
    theme: document.documentElement.getAttribute('data-theme'),
    opacity: opacity,
    animationsRun: anims.length,
    h1Animation: h1cs.animationName + ' ' + h1cs.animationDuration,
    transition: getComputedStyle(document.getElementById('theme-toggle')).transitionDuration,
    scrollBehavior: getComputedStyle(document.documentElement).scrollBehavior,
    scrollWidth: document.documentElement.scrollWidth,
    bodyScrollWidth: document.body.scrollWidth,
    overflowing: overflowing,
    reduced: matchMedia('(prefers-reduced-motion: reduce)').matches,
    errs: window.__errs || []
  });
})()`;

const combos = [];
for (const width of [375, 1440]) for (const theme of ['light', 'dark']) for (const reduced of [false, true]) combos.push({ width, theme, reduced });

const results = [];
for (const c of combos) {
  await cdp.send('Emulation.setDeviceMetricsOverride', { width: c.width, height: 900, deviceScaleFactor: 1, mobile: false });
  await cdp.send('Emulation.setEmulatedMedia', {
    features: [
      { name: 'prefers-color-scheme', value: c.theme },
      { name: 'prefers-reduced-motion', value: c.reduced ? 'reduce' : 'no-preference' }
    ]
  });
  await cdp.send('Page.navigate', { url: PAGE + '?theme=' + c.theme + '&t=' + Date.now() });
  await sleep(400);
  for (let i = 0; i < 40; i++) {           /* 等 DOMContentLoaded */
    const ready = await cdp.eval('document.readyState');
    if (ready === 'complete') break;
    await sleep(150);
  }
  const d = JSON.parse(await cdp.eval(PROBE));
  results.push({ c, d });
}

/* 报告 */
let fail = 0;
for (const { c, d } of results) {
  const label = `${c.width}px / ${c.theme} / reduced-motion=${c.reduced}`;
  console.log('\n================ ' + label + ' (实际 viewport ' + d.viewport + ') ================');
  const allVisible = Object.values(d.opacity).every(v => parseFloat(v) > 0.99);
  const noScroll = d.scrollWidth <= d.viewport && d.bodyScrollWidth <= d.viewport;
  const noErr = d.errs.length === 0;
  if (!allVisible || !noScroll || !noErr) fail++;
  console.log((allVisible ? 'PASS' : 'FAIL') + '  动效结束后 opacity   : ' + JSON.stringify(d.opacity) + '  (动画数 ' + d.animationsRun + ')');
  console.log((noScroll ? 'PASS' : 'FAIL') + '  横向滚动            : scrollWidth=' + d.scrollWidth + ' / viewport=' + d.viewport + ' / body=' + d.bodyScrollWidth);
  console.log((d.overflowing.length === 0 ? 'PASS' : 'FAIL') + '  溢出元素            : ' + (d.overflowing.length ? d.overflowing : '无'));
  console.log((noErr ? 'PASS' : 'FAIL') + '  控制台错误          : ' + (d.errs.length ? d.errs : '无'));
  console.log('      动画/过渡/滚动    : ' + d.h1Animation + ' | transition ' + d.transition + ' | scroll-behavior ' + d.scrollBehavior + ' | reduced=' + d.reduced);
}

console.log('\n===== 汇总：' + (results.length - fail) + ' / ' + results.length + ' 个组合全项通过 =====');
ws.close();
chrome.kill();
process.exit(fail ? 1 : 0);

